const src = $json || {};
const body = (src.body && typeof src.body === 'object') ? src.body : src;
const headers = src.headers || {};

const cfg = {
  locationId: src.locationId,
  apiBaseUrl: String(src.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, ''),
  apiKey: src.apiKey,
  defaultDryRun: !!src.defaultDryRun,
  helpFieldKey: String(src.helpFieldKey || 'contact.how_can_we_help'),
  helpFieldId: String(src.helpFieldId || ''),
  authHeaderName: String(src.authHeaderName || 'x-intake-key').toLowerCase(),
  authHeaderValue: String(src.authHeaderValue || ''),
};

if (!cfg.locationId) throw new Error('Missing Config.locationId');
if (!cfg.apiKey) throw new Error('Missing Config.apiKey');

const incomingAuth = headers[cfg.authHeaderName] || headers[cfg.authHeaderName.toLowerCase()] || '';
if (cfg.authHeaderValue && incomingAuth !== cfg.authHeaderValue) {
  return [{ json: { ok: false, error: 'unauthorized', message: 'Invalid intake auth header' } }];
}

const dryRun = body.dryRun === undefined ? cfg.defaultDryRun : !!body.dryRun;

function clean(v) { return String(v ?? '').trim(); }
function splitFullName(fullName) {
  const raw = clean(fullName).replace(/\s+/g, ' ');
  if (!raw) return { firstName: '', lastName: '' };
  const parts = raw.split(' ');
  if (parts.length === 1) return { firstName: parts[0], lastName: '' };
  return { firstName: parts[0], lastName: parts.slice(1).join(' ') };
}

const fullName = clean(body.full_name || body.fullName || body.name || body['First & Last Name']);
const { firstName, lastName } = splitFullName(fullName);
const email = clean(body.email);
const phone = clean(body.phone || body.mobile || body.phone_number);
const website = clean(body.website || body.company_website || body.companyWebsite || body.url);
const howCanWeHelp = clean(body.message || body.how_can_we_help || body.howCanWeHelp || body['How can we help?']);
let contactId = clean(body.contactId || body.contact_id || body.id);

if (!contactId && !email && !phone) {
  return [{
    json: {
      ok: false,
      error: 'missing_identity',
      message: 'Provide contactId or at least email/phone in payload.',
      expected: ['contactId', 'email', 'phone'],
    },
  }];
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

const headersGhl = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function apiRequest({ method, path, body }) {
  const options = {
    method,
    url: `${cfg.apiBaseUrl}${path}`,
    headers: headersGhl,
    json: true,
  };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
      requestBody: body,
    };
  }
}

const upsertBody = {
  locationId: cfg.locationId,
  email: email || undefined,
  phone: phone || undefined,
  firstName: firstName || undefined,
  lastName: lastName || undefined,
  website: website || undefined,
};
Object.keys(upsertBody).forEach((k) => upsertBody[k] === undefined && delete upsertBody[k]);

if (!contactId) {
  const upsertRes = await apiRequest.call(this, { method: 'POST', path: '/contacts/upsert', body: upsertBody });
  if (!upsertRes.ok) {
    return [{ json: { ok: false, error: 'upsert_failed', details: upsertRes.data, requestBody: upsertBody } }];
  }
  contactId = upsertRes.data?.contact?.id || upsertRes.data?.id || upsertRes.data?.contactId || '';
  if (!contactId) {
    return [{ json: { ok: false, error: 'contact_id_missing_after_upsert', details: upsertRes.data } }];
  }
}

if (dryRun) {
  return [{
    json: {
      ok: true,
      dryRun: true,
      action: 'would_upsert_contact_and_update_help_field',
      contactId,
      mapped: {
        full_name: fullName,
        first_name: firstName,
        last_name: lastName,
        email,
        website,
        how_can_we_help: howCanWeHelp,
      },
      helpField: { id: cfg.helpFieldId, key: cfg.helpFieldKey },
    },
  }];
}

const updateBodies = [
  {
    website: website || undefined,
    customFields: cfg.helpFieldId && howCanWeHelp ? [{ id: cfg.helpFieldId, value: howCanWeHelp }] : undefined,
  },
  {
    website: website || undefined,
    customFields: cfg.helpFieldId && howCanWeHelp ? [{ id: cfg.helpFieldId, field_value: howCanWeHelp }] : undefined,
  },
  {
    website: website || undefined,
    customField: howCanWeHelp ? { [cfg.helpFieldId || cfg.helpFieldKey]: howCanWeHelp } : undefined,
  },
  {
    website: website || undefined,
    customField: howCanWeHelp ? { [cfg.helpFieldKey]: howCanWeHelp } : undefined,
  },
].map((b) => {
  const cleanObj = { ...b };
  Object.keys(cleanObj).forEach((k) => cleanObj[k] === undefined && delete cleanObj[k]);
  return cleanObj;
}).filter((b) => Object.keys(b).length > 0);

let updateOk = null;
let lastErr = null;
for (const bodyTry of updateBodies) {
  const r = await apiRequest.call(this, { method: 'PUT', path: `/contacts/${contactId}`, body: bodyTry });
  if (r.ok) {
    updateOk = { bodyUsed: bodyTry, response: r.data };
    break;
  }
  lastErr = r;
}

if (!updateOk) {
  return [{
    json: {
      ok: false,
      error: 'contact_update_failed',
      contactId,
      attemptedBodies: updateBodies,
      details: lastErr?.data || lastErr,
    },
  }];
}

return [{
  json: {
    ok: true,
    dryRun: false,
    action: 'contact_updated',
    contactId,
    mapped: {
      first_name: firstName,
      last_name: lastName,
      website,
      how_can_we_help: howCanWeHelp,
    },
    updateRequestBodyUsed: updateOk.bodyUsed,
  },
}];

